 92 // explicitScheme matches a value that starts with a URL scheme, as opposed to
 93 // one that only has "://" somewhere in its path or query.
 94 var explicitScheme = regexp.MustCompile(`^[A-Za-z][A-Za-z0-9+.-]*://`)
 95 
 96 // usableProxyValue follows Go's parseProxy (url.Parse, then a retry with
 97 // "http://" in front for a value without a scheme) and is stricter on three
 98 // points, because Go ignores an unusable value and FromEnvironment alone
 99 // cannot tell it from "no proxy":
100 //   - the host must not be empty;
101 //   - a value holding "@" must end up with userinfo, otherwise the credential
102 //     was mangled (an unescaped "/", "?" or "#" before the "@") and the text
103 //     before it became the host;
104 //   - the host must be printable UTF-8, since it ends up on screen.
105 func usableProxyValue(value string) bool {
106     explicit := explicitScheme.MatchString(value)
107     u, err := url.Parse(value)
108     switch {
109     case err != nil && explicit:
110         return false
111     case err == nil && u.Scheme != "" && u.Host != "":
112         // Parsed as written.
113     case err == nil && explicit:
114         // An explicit scheme with no host, such as "http://".
115         return false
116     default:
117         u, err = url.Parse("http://" + value)
118         if err != nil {
119             return false
120         }
121     }
122     if u.Host == "" || (u.User == nil && strings.Contains(value, "@")) {
123         return false
124     }
125     return isPrintable(u.Host)
126 }
127 
128 // isPrintable reports whether s is valid UTF-8 made of printable runes only.
129 func isPrintable(s string) bool {
130     if !utf8.ValidString(s) {
131         return false
132     }
133     for _, r := range s {
134         if !unicode.IsPrint(r) {
135             return false
136         }
137     }
138     return true
139 }
140 
141 // isLoopbackHost reports whether host is localhost or a loopback address.
142 func isLoopbackHost(host string) bool {
143     if strings.EqualFold(host, "localhost") {
144         return true
145     }
146     addr, err := netip.ParseAddr(host)
147     return err == nil && addr.Unmap().IsLoopback()
148 }
149 
150 // defaultPorts are the ports Display shows when the URL names none.
151 var defaultPorts = map[string]string{
152     "http":    "80",
153     "https":   "443",
154     "socks5":  "1080",
155     "socks5h": "1080",
156 }
157 
158 // Display renders a proxy URL as scheme://host:port and nothing else: never
159 // userinfo, path, query, fragment or IPv6 zone. It is the only way a proxy leaves this
160 // package for the screen. A scheme with no known default port shows no port
161 // unless the URL names one. Display(nil) is empty.
162 func Display(proxy *url.URL) string {
163     if proxy == nil {
164         return ""
165     }
166     port := proxy.Port()
167     if port == "" {
168         port = defaultPorts[strings.ToLower(proxy.Scheme)]
169     }
170     // The zone of a link-local address can be any text: drop it.
171     host, _, _ := strings.Cut(proxy.Hostname(), "%")
172     if port != "" {
173         host = net.JoinHostPort(host, port)
174     } else if strings.Contains(host, ":") {
175         host = "[" + host + "]"
176     }
177     return proxy.Scheme + "://" + host
178 }
