  14 // DEVDESK-582, criterion 6 end to end and without a network: the real
  15 // systemEnv.ProxyFor reads the real process environment, so each case runs the
  16 // test binary again with exactly the variables it wants. The fake env answers
  17 // every other question; only the proxy one is delegated to the system env.
  18 
  19 const (
  20     e2eHelperEnv   = "NETCHECK_TEST_PROXY_E2E_HELPER"
  21     e2eResultMark  = "NETCHECK_E2E_RESULT:"
  22     e2eSecretValue = secretUser + ":" + secretPass
  23 )
  24 
  25 type e2eResult struct {
  26     Dump    string  `json:"dump"`
  27     Verdict Verdict `json:"verdict"`
  28     Summary string  `json:"summary"`
  29     Reason  Reason  `json:"reason"`
  30 }
  31 
  32 // TestProxyE2EHelper is the child half. It does nothing in a normal run.
  33 func TestProxyE2EHelper(t *testing.T) {
  34     if os.Getenv(e2eHelperEnv) != "1" {
  35         t.Skip("child of TestTheProxyRowNeverCarriesACredentialEndToEnd")
  36     }
  37     set := DefaultSettings()
  38     env := fakeEnv{proxy: SystemEnv(set).ProxyFor}
  39     res, err := Run(context.Background(), target(), env, set)
  40     if err != nil {
  41         t.Fatalf("Run: %v", err)
  42     }
  43     row, ok := res.Get(CheckProxy)
  44     if !ok {
  45         t.Fatal("the run left no proxy check")
  46     }
  47     out, err := json.Marshal(e2eResult{
  48         Dump:    fmt.Sprintf("%+v", res.All()),
  49         Verdict: row.Verdict,
  50         Summary: row.Summary,
  51         Reason:  row.Reason,
  52     })
  53     if err != nil {
  54         t.Fatalf("marshal: %v", err)
  55     }
  56     fmt.Println(e2eResultMark + string(out))
  57 }
  58 
  59 // runE2EChild runs the child with the proxy variables of the parent removed and
  60 // exactly vars set.
  61 func runE2EChild(t *testing.T, vars map[string]string) e2eResult {
  62     t.Helper()
  63     drop := []string{"HTTPS_PROXY", "HTTP_PROXY", "NO_PROXY", "ALL_PROXY", "REQUEST_METHOD", e2eHelperEnv}
  64     var env []string
  65     for _, kv := range os.Environ() {
  66         name, _, _ := strings.Cut(kv, "=")
  67         keep := true
  68         for _, d := range drop {
  69             if strings.EqualFold(name, d) {
  70                 keep = false
  71             }
  72         }
  73         if keep {
  74             env = append(env, kv)
  75         }
  76     }
  77     // GORACE: under -race each child would otherwise sleep a second at exit.
  78     env = append(env, "GORACE=atexit_sleep_ms=0", e2eHelperEnv+"=1")
  79     for k, v := range vars {
  80         env = append(env, k+"="+v)
  81     }
  82     cmd := exec.Command(os.Args[0], "-test.run=^TestProxyE2EHelper$", "-test.count=1")
  83     cmd.Env = env
  84     var out bytes.Buffer
  85     cmd.Stdout, cmd.Stderr = &out, &out
  86     if err := cmd.Run(); err != nil {
  87         t.Fatalf("running the helper: %v\n%s", err, out.String())
  88     }
  89     for _, line := range strings.Split(out.String(), "\n") {
  90         rest, ok := strings.CutPrefix(strings.TrimSpace(line), e2eResultMark)
  91         if !ok {
  92             continue
  93         }
  94         var r e2eResult
  95         if err := json.Unmarshal([]byte(rest), &r); err != nil {
  96             t.Fatalf("decode the helper's answer %q: %v", rest, err)
  97         }
  98         return r
  99     }
 100     t.Fatalf("the helper printed no %q line:\n%s", e2eResultMark, out.String())
 101     return e2eResult{}
 102 }
